const allItems = $input.all().map(i => i.json);

const items = allItems
  .filter(i => i.code === 200 && i.body)
  .map(i => ({
    json: {
      item_id: i.body.id,
      title: i.body.title,
      price: i.body.price,
      original_price: i.body.original_price,
      sale_price: i.body.sale_price,
      base_price: i.body.base_price,
      currency_id: i.body.currency_id,
      available_quantity: i.body.available_quantity,
      permalink: i.body.permalink,
      thumbnail: i.body.thumbnail,
      status: i.body.status
    }
  }));

return items;

const originalItems = $('Prepare Items').all().map(i => i.json);
const promoResponses = $input.all().map(i => i.json);
const query = $('Execute Workflow Trigger').first().json.query || '';

const excludeIds = ['MLA1427405068', 'MLA2032050504'];

const duraciones = {
  'MLA1675597774': 180,
  'MLA1436553470': 45,
  'MLA2348847440': 90,
  'MLA2470519598': 30,
  'MLA1101767933': 30,
  'MLA1532172427': 30,
  'MLA1113722322': 60,
  'MLA1327394570': 90,
  'MLA1436505318': 30,
  'MLA896594083': 90,
  'MLA1532695445': 60,
  'MLA1436492592': 90,
  'MLA2367830382': 60,
  'MLA1327110821': 45,
};

// Build price lookup from original items for DEAL matching
const itemPriceLookup = {};
originalItems.forEach(item => {
  const price = item.price || item.base_price;
  if (price) {
    if (!itemPriceLookup[price]) itemPriceLookup[price] = [];
    itemPriceLookup[price].push(item.item_id);
  }
});

// promoMap: itemId -> { promoPrice, originalPrice, status, priority }
const promoMap = {};
const statusPriority = { 'started': 3, 'active': 2, 'candidate': 1 };

promoResponses.forEach(resp => {
  if (!resp || resp.error || resp.message) return;

  // Normalize: could be single promo, array, or { results: [...] }
  let promos = [];
  if (Array.isArray(resp)) {
    promos = resp;
  } else if (resp.results && Array.isArray(resp.results)) {
    promos = resp.results;
  } else if (resp.type || resp.status) {
    promos = [resp];
  }

  promos.forEach(promo => {
    if (!promo) return;

    // Skip PRICE_DISCOUNT with price=0 (suggestions, not real promos)
    if (promo.type === 'PRICE_DISCOUNT' && (!promo.new_price || promo.new_price === 0)) return;

    const promoPrice = promo.new_price || promo.price;
    if (!promoPrice || promoPrice <= 0) return;

    const promoOriginal = promo.original_price || promo.old_price || null;
    const promoStatus = promo.status || 'candidate';
    const priority = statusPriority[promoStatus] || 0;

    // METHOD 1: Extract MLA ID from ref_id (SMART/OFFER promos)
    let matchedItemId = null;
    if (promo.ref_id) {
      const match = promo.ref_id.match(/(MLA\d+)/);
      if (match) matchedItemId = match[1];
    }

    // METHOD 2: Match by original_price (DEAL promos) - apply to ALL candidates with same price
    if (!matchedItemId && promoOriginal) {
      const candidates = itemPriceLookup[promoOriginal];
      if (candidates && candidates.length >= 1) {
        candidates.forEach(candidateId => {
          const existing = promoMap[candidateId];
          if (!existing || priority > existing.priority || (priority === existing.priority && promoPrice < existing.promoPrice)) {
            promoMap[candidateId] = {
              promoPrice,
              originalPrice: promoOriginal,
              status: promoStatus,
              priority
            };
          }
        });
        return; // Already applied to all candidates
      }
    }

    if (!matchedItemId) return; // Can't identify item, skip

    // Keep best promo: higher status priority wins, then lower price
    const existing = promoMap[matchedItemId];
    if (!existing || priority > existing.priority || (priority === existing.priority && promoPrice < existing.promoPrice)) {
      promoMap[matchedItemId] = {
        promoPrice,
        originalPrice: promoOriginal,
        status: promoStatus,
        priority
      };
    }
  });
});

// Filter and format
let products = originalItems.filter(p => !excludeIds.includes(p.item_id));

if (query) {
  const q = query.toLowerCase();
  products = products.filter(p => p.title && p.title.toLowerCase().includes(q));
}

if (products.length === 0) {
  return [{ json: { result: 'No se encontraron productos' + (query ? ` con "${query}"` : '') + '.' } }];
}

let result = `\ud83d\udce6 *${products.length} producto(s) encontrado(s)*`;
if (query) result += ` con "${query}"`;
result += ':\n\n';

products.forEach((p, i) => {
  const precio = p.price ? `$${p.price.toLocaleString('es-AR')}` : 'Sin precio';
  const dias = duraciones[p.item_id];
  const duracion = dias ? `${dias} d\u00edas` : 'Consultar';

  let promoTag = '';
  let precioLinea = precio;

  // Priority 1: seller-promotions (promoMap)
  const promo = promoMap[p.item_id];
  if (promo && promo.promoPrice) {
    const promoOriginal = promo.originalPrice || p.price;
    if (promo.promoPrice < promoOriginal) {
      const descuento = Math.round((1 - promo.promoPrice / promoOriginal) * 100);
      precioLinea = `~$${promoOriginal.toLocaleString('es-AR')}~ \u2192 *$${promo.promoPrice.toLocaleString('es-AR')}*`;
      promoTag = ` \ud83d\udd25 ${descuento}% OFF`;
    }
  }
  // Priority 2: sale_price from multiget
  else if (p.sale_price && typeof p.sale_price === 'object' && p.sale_price.amount && p.sale_price.amount < p.price) {
    const descuento = Math.round((1 - p.sale_price.amount / p.price) * 100);
    precioLinea = `~$${p.price.toLocaleString('es-AR')}~ \u2192 *$${p.sale_price.amount.toLocaleString('es-AR')}*`;
    promoTag = ` \ud83d\udd25 ${descuento}% OFF`;
  }
  // Priority 3: original_price from multiget
  else if (p.original_price && p.original_price > p.price) {
    const descuento = Math.round((1 - p.price / p.original_price) * 100);
    precioLinea = `~$${p.original_price.toLocaleString('es-AR')}~ \u2192 *${precio}*`;
    promoTag = ` \ud83d\udd25 ${descuento}% OFF`;
  }
  // Priority 4: base_price from multiget
  else if (p.base_price && p.base_price > p.price) {
    const descuento = Math.round((1 - p.price / p.base_price) * 100);
    precioLinea = `~$${p.base_price.toLocaleString('es-AR')}~ \u2192 *${precio}*`;
    promoTag = ` \ud83d\udd25 ${descuento}% OFF`;
  }

  result += `${i + 1}. *${p.title}*${promoTag}\n`;
  result += `   \ud83d\udcb0 ${precioLinea}\n`;
  result += `   \ud83d\udcc5 Duraci\u00f3n: ${duracion}\n`;
  result += `   \ud83d\udce6 Stock: ${p.available_quantity} unidades\n`;
  result += `   \ud83d\udd17 ${p.permalink}\n\n`;
});

return [{ json: { result } }];
